() => {
  const text = document.body.innerText || '';
  const unregistered = [...text.matchAll(/Not registered|Action required|Pending|Draft package|Register package name/gi)].map(m => m[0]);
  return {
    url: location.href,
    title: document.title,
    unregisteredHits: unregistered.slice(0, 20),
    hasRegisterCta: /Register package name/i.test(text),
    hasAllRegistered: /successfully registered/i.test(text)
  };
}

() => {
  const options = [...document.querySelectorAll('[role="option"], [role="listbox"] *')].map(el => ({
    role: el.getAttribute('role'),
    text: (el.innerText || '').trim(),
    aria: el.getAttribute('aria-label')
  })).filter(x => x.text || x.aria);
  const unique = [];
  const seen = new Set();
  for (const o of options) {
    const k = o.text || o.aria;
    if (!seen.has(k)) { seen.add(k); unique.push(o); }
  }
  return unique.slice(0, 30);
}

() => {
  const draft = [...document.querySelectorAll('[role="option"]')].find(el => (el.innerText || '').trim() === 'Draft');
  if (!draft) return { found: false };
  draft.click();
  return { found: true, clicked: 'Draft' };
}

() => {
  const btn = [...document.querySelectorAll('button')].find(el => (el.getAttribute('aria-label') || el.innerText || '').includes('Filter by'));
  if (btn) btn.click();
  return { clicked: !!btn, label: btn ? (btn.getAttribute('aria-label') || btn.innerText) : null };
}

() => {
  const opt = [...document.querySelectorAll('[role="option"]')].find(el => (el.innerText || '').trim() === 'In review');
  if (!opt) return { found: false, options: [...document.querySelectorAll('[role="option"]')].map(el => el.innerText.trim()) };
  opt.click();
  return { found: true, clicked: 'In review' };
}
